<script setup lang="ts">
import { indentSelection } from '@/services/indent'
import { computed, ref, watch } from 'vue'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from '@/components/ui/dialog'
import { Select, SelectTrigger, SelectValue, SelectContent, SelectGroup, SelectItem } from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { Field, FieldGroup, FieldLabel } from '@/components/ui/field'
import { markdown } from '@/services/markdown'
import { useWorkbench } from '@/stores/workbench'
import type { Document } from '@/types'
import { toast } from 'vue-sonner'
import { GripVerticalIcon, Trash2Icon, SlidersHorizontalIcon, AlignLeftIcon, AlignCenterIcon, AlignRightIcon, PlusIcon } from '@lucide/vue'
import { PopoverRoot, PopoverTrigger, PopoverPortal, PopoverContent } from 'reka-ui'
const props = defineProps<{ open: boolean; kind: 'table' | 'code'; document?: Document; blockIndex?:number }>(), emit = defineEmits<{ 'update:open': [value: boolean] }>()
const store = useWorkbench(), target = ref('new'), cells = ref<string[][]>([]), language = ref(''), code = ref(''), snapshot = ref(''), alignments=ref<string[]>([]),pasteText=ref('')
const draggingRow = ref<number | null>(null), draggingColumn = ref<number | null>(null)
const tableGrid = ref<HTMLElement>()
const blocks = computed(() => { const tokens = markdown.parse(snapshot.value, {}); return tokens.flatMap((t, i) => {
  if (props.kind === 'code' && t.type === 'fence' && t.map) return [{ start: t.map[0], end: t.map[1], rows: [] as string[][], align: [] as string[], language: t.info.trim(), code: t.content }]
  if (props.kind !== 'table' || t.type !== 'table_open' || !t.map) return []
  const rows: string[][] = [], align: string[] = []; let row: string[] = []
  for (const cell of tokens.slice(i + 1)) { if (cell.type === 'table_close') break; if (cell.type === 'tr_open') { row = []; rows.push(row) }; if (cell.type === 'inline') row.push(cell.content); if (cell.type === 'th_open') align.push(String(cell.attrGet('style') || '')) }
  return [{ start: t.map[0], end: t.map[1], rows, align, language: '', code: '' }]
}) })
function load() { const block = blocks.value[Number(target.value)]; cells.value = block?.rows.length?block.rows.map(row => [...row]):[['标题 1', '标题 2'], ['', '']]; alignments.value=cells.value[0]!.map((_,i)=>block?.align[i]?.includes('center')?'center':block?.align[i]?.includes('right')?'right':block?.align[i]?.includes('left')?'left':'default');pasteText.value=''; language.value = block?.language || 'text'; code.value = block?.code || '' }
watch(() => props.open, open => { if (open) { snapshot.value = props.document?.text || ''; target.value = props.blockIndex===undefined?'new':String(props.blockIndex); load() } })
watch(target, load)
function apply() {
  const d = props.document; if (!d) return
  if (d.text !== snapshot.value) { toast.warning('文档已变化，请重新打开此编辑窗口。'); return }
  const block = blocks.value[Number(target.value)]
  let value: string
  if (props.kind === 'table') { const escape = (cell: string) => cell.replace(/\r?\n/g, '<br>').replace(/(?<!\\)\|/g, '\\|'); const row = (values: string[]) => '| ' + values.map(escape).join(' | ') + ' |'; const align = cells.value[0]!.map((_, index) => { const style = alignments.value[index] || ''; return style.includes('center') ? ':---:' : style.includes('right') ? '---:' : style.includes('left') ? ':---' : '---' }); value = [row(cells.value[0]!), row(align), ...cells.value.slice(1).map(row)].join('\n') + '\n' }
  else { const fence = '`'.repeat(Math.max(3, ...Array.from(code.value.matchAll(/`+/g), m => m[0].length + 1))); value = `${fence}${language.value.replace(/[\r\n\x00-\x1f]/g,'').slice(0,256)}\n${code.value.replace(/\n$/, '')}\n${fence}\n` }
  const lines = snapshot.value.split('\n'); const next = block ? [...lines.slice(0,block.start), value.replace(/\n$/, ''), ...lines.slice(block.end)].join('\n') : snapshot.value.replace(/\s*$/, '') + '\n\n' + value
  store.change(d, next,'structure'); d.generation++; emit('update:open', false)
}
function moveRow(i:number,delta:number){const j=i+delta;if(i<1||j<1||j>=cells.value.length)return;const item=cells.value.splice(i,1)[0]!;cells.value.splice(j,0,item)}
function moveColumn(i:number,delta:number){const j=i+delta;if(j<0||j>=cells.value[0]!.length)return;for(const row of cells.value){const item=row.splice(i,1)[0]!;row.splice(j,0,item)}const a=alignments.value.splice(i,1)[0]!;alignments.value.splice(j,0,a)}
function dropRow(index:number){const from=draggingRow.value;if(from===null||from===0||index===0||from===index)return;const [row]=cells.value.splice(from,1);if(row)cells.value.splice(index,0,row);draggingRow.value=index}
function dropColumn(index:number){const from=draggingColumn.value;if(from===null||from===index)return;for(const row of cells.value){const [cell]=row.splice(from,1);if(cell!==undefined)row.splice(index,0,cell)}const [alignment]=alignments.value.splice(from,1);if(alignment!==undefined)alignments.value.splice(index,0,alignment);draggingColumn.value=index}
function pointerSortStart(axis:'row'|'column',index:number,event:PointerEvent){if(event.button!==0)return;event.preventDefault();(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);if(axis==='row')draggingRow.value=index;else draggingColumn.value=index}
function pointerSortMove(axis:'row'|'column',event:PointerEvent){const rect=tableGrid.value?.getBoundingClientRect();if(!rect)return;if(axis==='row'){const rows=[...tableGrid.value!.querySelectorAll<HTMLElement>('[data-row-index]')],targetRow=rows.find(el=>{const r=el.getBoundingClientRect();return event.clientY>=r.top&&event.clientY<=r.bottom});if(targetRow)dropRow(Number(targetRow.dataset.rowIndex))}else{const headers=[...tableGrid.value!.querySelectorAll<HTMLElement>('[data-column-index]')],targetColumn=headers.find(el=>{const r=el.getBoundingClientRect();return event.clientX>=r.left&&event.clientX<=r.right});if(targetColumn)dropColumn(Number(targetColumn.dataset.columnIndex))}}
function pointerSortEnd(axis:'row'|'column'){if(axis==='row')draggingRow.value=null;else draggingColumn.value=null}
function keyboardMoveRow(index:number,event:KeyboardEvent){if(event.altKey&&(event.key==='ArrowUp'||event.key==='ArrowDown')){event.preventDefault();moveRow(index,event.key==='ArrowUp'?-1:1)}}
function keyboardMoveColumn(index:number,event:KeyboardEvent){if(event.altKey&&(event.key==='ArrowLeft'||event.key==='ArrowRight')){event.preventDefault();moveColumn(index,event.key==='ArrowLeft'?-1:1)}}
function pasteTable(){const rows=pasteText.value.replace(/\r\n/g,'\n').trimEnd().split('\n').map(r=>r.split('\t'));const width=Math.max(...rows.map(r=>r.length));if(rows.length>100||width>20){toast.error('最多 100 行、20 列');return}cells.value=rows.map(r=>Array.from({length:width},(_,i)=>r[i]||''));alignments.value=Array(width).fill('default')}
function codeKey(e:KeyboardEvent){if(e.key!=='Tab')return;e.preventDefault();const el=e.target as HTMLTextAreaElement,result=indentSelection(el.value,el.selectionStart,el.selectionEnd,e.shiftKey);el.value=result.text;el.setSelectionRange(result.start,result.end);code.value=result.text}
</script>
<template><Dialog :open="open" @update:open="emit('update:open',$event)"><DialogContent class="productivity-dialog sm:max-w-3xl"><DialogHeader><DialogTitle>{{ kind === 'table' ? '编辑表格' : '编辑代码块' }}</DialogTitle><DialogDescription>{{ kind === 'table' ? '选择已有表格或在文末插入新表格，支持增删行列。' : '选择代码块并调整语言，或在文末插入新代码块。' }}</DialogDescription></DialogHeader>
  <FieldGroup><Field><FieldLabel>编辑对象</FieldLabel><Select v-model="target"><SelectTrigger aria-label="编辑对象"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectItem value="new">在文末插入</SelectItem><SelectItem v-for="(block,index) in blocks" :key="index" :value="String(index)">第 {{ index+1 }} 个{{ kind === 'table' ? '表格' : '代码块' }} · 第 {{ block.start+1 }} 行</SelectItem></SelectGroup></SelectContent></Select></Field></FieldGroup>
  <template v-if="kind === 'table'"><div ref="tableGrid" class="structure-table"><div class="structure-column-tools" :style="{'--structure-columns':cells[0]!.length}" aria-label="列设置"><div class="structure-column-grip" aria-hidden="true"></div><div v-for="(_,c) in cells[0]" :key="c" class="structure-column-cell" :class="{'structure-dragging':draggingColumn===c}" :data-column-index="c"><button type="button" class="structure-grip structure-column-drag" :aria-label="`拖动第 ${c+1} 列排序`" title="拖动排序；也可按 Alt+←/→" @pointerdown="pointerSortStart('column',c,$event)" @pointermove="draggingColumn!==null&&pointerSortMove('column',$event)" @pointerup="pointerSortEnd('column')" @pointercancel="pointerSortEnd('column')" @keydown="keyboardMoveColumn(c,$event)"><GripVerticalIcon class="size-4"/></button><div class="structure-column-actions"><PopoverRoot><PopoverTrigger as-child><Button variant="ghost" size="icon-xs" :aria-label="`设置第 ${c+1} 列对齐方式`" title="对齐方式"><SlidersHorizontalIcon/></Button></PopoverTrigger><PopoverPortal><PopoverContent side="top" :side-offset="6" class="structure-align-popover" :aria-label="`第 ${c+1} 列对齐方式`"><button v-for="option in [{value:'left',label:'左对齐',icon:AlignLeftIcon},{value:'center',label:'居中',icon:AlignCenterIcon},{value:'right',label:'右对齐',icon:AlignRightIcon},{value:'default',label:'默认',icon:AlignLeftIcon}]" :key="option.value" type="button" :class="{'is-selected':alignments[c]===option.value}" :aria-label="option.label" :title="option.label" @click="alignments[c]=option.value"><component :is="option.icon" class="size-4"/></button></PopoverContent></PopoverPortal></PopoverRoot><Button variant="destructive" size="icon-xs" :disabled="cells[0]!.length <= 1" :aria-label="`删除第 ${c+1} 列`" :title="`删除第 ${c+1} 列`" @click="cells.forEach(row => row.splice(c,1));alignments.splice(c,1)"><Trash2Icon/></Button></div></div><Button variant="outline" size="icon-sm" class="structure-add-column" :disabled="cells[0]!.length>=20" aria-label="添加一列" title="添加一列" @click="cells.forEach(row => row.push(''));alignments.push('default')"><PlusIcon/></Button></div><div v-for="(row,r) in cells" :key="r" class="structure-row" :class="{'structure-dragging':draggingRow===r}" :style="{'--structure-columns':cells[0]!.length}" :data-row-index="r"><button type="button" class="structure-grip" :class="{'structure-grip-disabled':r===0}" :disabled="r===0" :aria-label="`拖动第 ${r+1} 行排序`" :title="r===0?'标题行固定':'拖动排序；也可按 Alt+↑/↓'" @pointerdown="r>0&&pointerSortStart('row',r,$event)" @pointermove="draggingRow!==null&&pointerSortMove('row',$event)" @pointerup="pointerSortEnd('row')" @pointercancel="pointerSortEnd('row')" @keydown="keyboardMoveRow(r,$event)"><GripVerticalIcon class="size-4"/></button><Input v-for="(_,c) in row" :key="c" v-model="row[c]" :aria-label="`表格第 ${r+1} 行第 ${c+1} 列`"/><Button variant="destructive" size="icon-xs" :disabled="r === 0" :aria-label="`删除第 ${r+1} 行`" :title="`删除第 ${r+1} 行`" @click="cells.splice(r,1)"><Trash2Icon/></Button></div></div><div class="flex gap-2"><Button variant="outline" size="sm" :disabled="cells.length >= 100" @click="cells.push(cells[0]!.map(() => ''))"><PlusIcon/>添加一行</Button></div><Textarea v-model="pasteText" aria-label="粘贴表格数据" placeholder="粘贴从电子表格复制的数据（制表符分隔）" class="min-h-20 text-sm"/><Button variant="outline" :disabled="!pasteText" @click="pasteTable">导入粘贴表格</Button></template>
  <FieldGroup v-else><Field><FieldLabel>代码语言</FieldLabel><Select v-model="language"><SelectTrigger aria-label="代码语言"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectItem v-if="!['text','javascript','typescript','python','rust','html','css','json','bash','sql','markdown'].includes(language)" :value="language">{{ language || '无语言' }}</SelectItem><SelectItem v-for="name in ['text','javascript','typescript','python','rust','html','css','json','bash','sql','markdown']" :key="name" :value="name">{{ name }}</SelectItem></SelectGroup></SelectContent></Select></Field><Field><FieldLabel for="code-block-content">代码内容</FieldLabel><textarea id="code-block-content" v-model="code" class="code-block-input" spellcheck="false" @keydown="codeKey" /></Field></FieldGroup>
  <DialogFooter><Button variant="outline" @click="emit('update:open',false)">取消</Button><Button @click="apply">应用</Button></DialogFooter>
</DialogContent></Dialog></template>

